<?php include 'config.php'; admin_only(); $message=''; $type=''; if(isset($_POST['submit'])){ $id=trim($_POST['book_id']);$name=trim($_POST['book_name']);$author=trim($_POST['author']); $check=mysqli_prepare($conn,'SELECT book_id FROM books WHERE book_id=?');mysqli_stmt_bind_param($check,'s',$id);mysqli_stmt_execute($check); if(mysqli_num_rows(mysqli_stmt_get_result($check))){$message='That book ID is already in use.';$type='error';}else{$add=mysqli_prepare($conn,"INSERT INTO books (book_id,book_name,author,status) VALUES (?,?,?,'Available')");mysqli_stmt_bind_param($add,'sss',$id,$name,$author);if(mysqli_stmt_execute($add)){$message='Book added to the catalog successfully.';$type='success';}else{$message='Unable to add the book. Please check the database fields.';$type='error';}}} ?>
<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Add book | LibraryHub</title><link rel="stylesheet" href="assets/style.css"><link rel="stylesheet" href="https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css"></head><body><div class="app-shell"><main class="form-page"><section class="form-card"><a class="btn secondary" href="dashboard.php"><i class="fa-solid fa-arrow-left"></i> Dashboard</a><p class="eyebrow" style="margin-top:25px">Collection growth</p><h1>Add a new book</h1><p>Create a clear, searchable entry for a new title.</p><?php if($message): ?><div class="notice <?php echo $type; ?>"><?php echo e($message); ?></div><?php endif; ?><form method="post"><label>Library book ID</label><input name="book_id" required placeholder="e.g. BK-1024"><label>Book title</label><input name="book_name" required placeholder="Enter the title"><label>Author</label><input name="author" required placeholder="Enter the author name"><div class="form-actions"><button class="btn" name="submit"><i class="fa-solid fa-plus"></i> Add to catalog</button><a class="btn secondary" href="viewbook.php">Cancel</a></div></form></section></main></div></body></html>
